import 'package:flutter/material.dart'; import '../../models/course_model.dart'; import '../../repositories/lesson_repository.dart'; import '../../widgets/lesson_card.dart'; import 'lesson_details_page.dart'; class CourseDetailsPage extends StatelessWidget { final CourseModel course; const CourseDetailsPage({super.key,required this.course}); @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(course.name)),body:StreamBuilder(stream:LessonRepository().watch(course.id),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(12),children:[Text(course.description,style:Theme.of(c).textTheme.bodyLarge),const SizedBox(height:16),Text('الدروس',style:Theme.of(c).textTheme.titleLarge),...s.data!.map((l)=>LessonCard(lesson:l,onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>LessonDetailsPage(lesson:l)))))]); })); }